using System.IO; using System.Security.Cryptography; namespace SaarOSS.Rechnungsprogramm.Services; public static class FileIntegrityService { public static async Task<bool> VerifySha256Async(string filePath,string expectedHash,CancellationToken token=default){if(string.IsNullOrWhiteSpace(expectedHash)||expectedHash.Length!=64)return false;byte[] expected;try{expected=Convert.FromHexString(expectedHash);}catch(FormatException){return false;}await using var stream=File.OpenRead(filePath);var actual=await SHA256.HashDataAsync(stream,token);return CryptographicOperations.FixedTimeEquals(actual,expected);} }
